def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[i][j] for j in range(w)] for i in range(h)]
    bg = grid[0][0]
    special = get_special_cells(grid)

    # For value 1: if two 1s on anti-diagonal, fill that segment
    if 1 in special and len(special[1]) >= 2:
        for i in range(len(special[1])):
            for j in range(i + 1, len(special[1])):
                p1 = special[1][i]
                p2 = special[1][j]
                if are_on_same_diagonal(p1, p2) == 'anti':
                    cells = anti_diag_cells(p1, p2, grid)
                    for r, c in cells:
                        result[r][c] = 1

    # For other values: fill diagonals from single cells
    for val in special:
        if val == 1:
            continue
        # Find if this val is "lone" (not paired on any diagonal)
        is_lone = True
        for j in range(len(special[val])):
            for k in range(j + 1, len(special[val])):
                if are_on_same_diagonal(special[val][j], special[val][k]):
                    is_lone = False
                    break
            if not is_lone:
                break

        if is_lone:
            # Extend all diagonals from single cell
            for p in special[val]:
                cells = extend_all_diagonals(p, h, w)
                for r, c in cells:
                    # Don't overwrite 1s
                    if result[r][c] != 1:
                        result[r][c] = val

    return result

def anti_diag_cells(p1, p2, grid):
    """Cells on anti-diagonal between p1 and p2"""
    r1, c1 = p1
    r2, c2 = p2
    cells = []
    h, w = len(grid), len(grid[0])
    if r1 <= r2:
        for i in range(r1, r2 + 1):
            c = r1 + c1 - i
            if 0 <= c < w:
                cells.append((i, c))
    else:
        for i in range(r1, r2 - 1, -1):
            c = r1 + c1 - i
            if 0 <= c < w:
                cells.append((i, c))
    return cells

