def transform_fixed(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[i][j] for j in range(w)] for i in range(h)]
    bg = grid[0][0]
    special = {}
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val != bg:
                if val not in special:
                    special[val] = []
                special[val].append((i, j))

    def get_segment_main_diag(p1, p2):
        r1, c1 = p1
        r2, c2 = p2
        cells = []
        if r1 <= r2:
            for i in range(r1, r2 + 1):
                c = c1 + (i - r1)
                if 0 <= c < w:
                    cells.append((i, c))
        else:
            for i in range(r2, r1 + 1):
                c = c1 + (i - r1)
                if 0 <= c < w:
                    cells.append((i, c))
        return cells

    def extend_main_both(r, c, h, w):
        cells = {(r, c)}
        for i in range(1, h + w):
            nr, nc = r - i, c - i
            if 0 <= nr < h and 0 <= nc < w:
                cells.add((nr, nc))
            else:
                break
        for i in range(1, h + w):
            nr, nc = r + i, c + i
            if 0 <= nr < h and 0 <= nc < w:
                cells.add((nr, nc))
            else:
                break
        return cells

    # Rule 1: Fill segment between 1-pair on anti-diagonal, or same-value pair on main diagonal
    for val in list(special.keys()):
        if len(special[val]) >= 1:
            for i in range(len(special[val])):
                for j in range(i + 1, len(special[val])):
                    p1, p2 = special[val][i], special[val][j]
                    if p1[0] - p1[1] == p2[0] - p2[1]:  # main diagonal pair
                        cells = get_segment_main_diag(p1, p2)
                        for r, c in cells:
                            result[r][c] = val
                    elif p1[0] + p1[1] == p2[0] + p2[1]:  # anti-diagonal pair
                        if val == 1:
                            r_min, r_max = min(p1[0], p2[0]), max(p1[0], p2[0])
                            for r in range(r_min, r_max + 1):
                                c = (p1[0] + p1[1]) - r
                                if 0 <= c < w:
                                    result[r][c] = val

    # Rule 2: Extend single cells (no same-value diagonal pair)
    # But only if NOT 1, and only along main diagonals
    # Also, for 6: only extends if no row/col overlap with any 1
    for val in special:
        if val == 1:
            continue  # 1s never extend

        # Check for same-value diagonal pairs
        has_pair = False
        for i in range(len(special[val])):
            for j in range(i + 1, len(special[val])):
                p1, p2 = special[val][i], special[val][j]
                if p1[0] - p1[1] == p2[0] - p2[1] or p1[0] + p1[1] == p2[0] + p2[1]:
                    has_pair = True
                    break
            if has_pair:
                break

        # If this value has pairs, skip it
        if has_pair:
            continue

        # Extend each singleton along main diagonals
        for p in special[val]:
            r, c = p

            # Special rule: if 6, check no row/col overlap with 1s
            if val == 6:
                for r1, c1 in special.get(1, []):
                    if r1 == r or c1 == c:
                        continue  # Don't extend - overlap with 1
                # OK to extend
                for rr, cc in extend_main_both(r, c, h, w):
                    result[rr][cc] = val
            # For other values (like 8), just extend if no same-val diagonal pair

    return result

