def get_special_cells(grid):
    bg = grid[0][0]
    special = {}
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val != bg:
                if val not in special:
                    special[val] = []
                special[val].append((i, j))
    return special

def get_segment_cells_on_main_diag(p1, p2, h, w):
    r1, c1 = p1
    r2, c2 = p2
    cells = []
    if r1 <= r2:
        for i in range(r1, r2 + 1):
            c = c1 + (i - r1)
            if 0 <= c < w:
                cells.append((i, c))
    else:
        for i in range(r2, r1 + 1):
            c = c1 + (i - r1)
            if 0 <= c < w:
                cells.append((i, c))
    return cells

def main_diag_both_directions(r, c, h, w):
    cells = {(r, c)}
    diff = r - c
    for i in range(1, h + w):
        nr, nc = r - i, c - i
        if 0 <= nr < h and 0 <= nc < w:
            cells.add((nr, nc))
        else:
            break
    for i in range(1, h + w):
        nr, nc = r + i, c + i
        if 0 <= nr < h and 0 <= nc < w:
            cells.add((nr, nc))
        else:
            break
    return cells

def transform(grid):
